{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_scorecard AS WITH base AS ( SELECT branch_code, week_start, MAX(week_total_units) AS total_actual_units, MAX(week_total_combos) AS total_combos, MAX(weighted_mix_deviation) AS weighted_mix_deviation, MAX(mix_score) AS composite_score, COUNT_IF(combo_deviation_tier = \'Perfect\') AS num_combos_perfect, COUNT_IF(combo_deviation_tier = \'Okay\') AS num_combos_okay, COUNT_IF(combo_deviation_tier = \'Poor\') AS num_combos_poor, COUNT_IF(warehouse_constrained_flag = \'Yes\') AS combos_warehouse_constrained, COUNT_IF(warehouse_data_missing = \'Yes\') AS combos_missing_warehouse_data FROM snitch_db.maplemonk.fresh_mix_score GROUP BY branch_code, week_start ), with_zone_priority AS ( SELECT b.*, z.zone, pt.store_priority_tier, pt.current_month_target, pt.mtd_achieved, CASE WHEN pt.current_month_target > 0 THEN ROUND(100.0 * pt.mtd_achieved / pt.current_month_target, 1) ELSE NULL END AS pct_to_target FROM base b LEFT JOIN snitch_db.maplemonk.store_zone_map z ON b.branch_code = z.branch_code LEFT JOIN snitch_db.maplemonk.store_priority_tier pt ON b.branch_code = pt.branch_code ), top_offender AS ( SELECT branch_code, week_start, category AS top_offending_category, mix_deviation AS top_offending_deviation FROM ( SELECT branch_code, week_start, category, mix_deviation, ROW_NUMBER() OVER (PARTITION BY branch_code, week_start ORDER BY mix_deviation DESC) AS rn FROM snitch_db.maplemonk.fresh_mix_score ) WHERE rn = 1 ), with_branch AS ( SELECT w.*, mf.\"STORE NAME\" AS branch_name, t.top_offending_category, t.top_offending_deviation, ROUND(100.0 * w.combos_warehouse_constrained / NULLIF(w.total_combos, 0), 1) AS warehouse_constrained_pct FROM with_zone_priority w LEFT JOIN snitch_db.maplemonk.master_file mf ON w.branch_code = mf.\"STORE CODE\"::VARCHAR LEFT JOIN top_offender t ON w.branch_code = t.branch_code AND w.week_start = t.week_start ), with_trend AS ( SELECT *, LAG(weighted_mix_deviation) OVER (PARTITION BY branch_code ORDER BY week_start) AS prior_week_deviation, LAG(composite_score) OVER (PARTITION BY branch_code ORDER BY week_start) AS prior_week_score FROM with_branch ) SELECT branch_code, branch_name, zone, week_start, DATEADD(\'day\', 6, week_start) AS week_end, total_actual_units, total_combos, num_combos_perfect, num_combos_okay, num_combos_poor, weighted_mix_deviation, composite_score, store_priority_tier, current_month_target, mtd_achieved, pct_to_target, CASE WHEN composite_score NOT IN (\'Perfect\', \'Okay\', \'Poor\') THEN composite_score WHEN composite_score = \'Poor\' AND store_priority_tier = \'High Priority\' THEN \'Critical\' WHEN composite_score = \'Poor\' AND store_priority_tier = \'Medium Priority\' THEN \'Concern\' WHEN composite_score = \'Poor\' AND store_priority_tier = \'Low Priority\' THEN \'Low Concern\' WHEN composite_score = \'Okay\' AND store_priority_tier = \'High Priority\' THEN \'Watch\' ELSE composite_score END AS severity_adjusted_score, prior_week_score, CASE WHEN composite_score NOT IN (\'Perfect\', \'Okay\', \'Poor\') THEN \'N/A\' WHEN prior_week_deviation IS NULL THEN \'New\' WHEN weighted_mix_deviation < prior_week_deviation THEN \'Improving\' WHEN weighted_mix_deviation > prior_week_deviation THEN \'Declining\' ELSE \'Stable\' END AS score_trend, top_offending_category, top_offending_deviation, combos_warehouse_constrained, warehouse_constrained_pct, combos_missing_warehouse_data, RANK() OVER ( PARTITION BY week_start ORDER BY CASE WHEN composite_score IN (\'Perfect\',\'Okay\',\'Poor\') THEN weighted_mix_deviation END ASC NULLS LAST ) AS store_rank_this_week, RANK() OVER ( PARTITION BY week_start, store_priority_tier ORDER BY CASE WHEN composite_score IN (\'Perfect\',\'Okay\',\'Poor\') THEN weighted_mix_deviation END ASC NULLS LAST ) AS store_rank_within_tier FROM with_trend ORDER BY branch_code, week_start;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            